template:
enum Media {
    Book(u32),
    Audio(u32),
    Video { id: u32 },
}

fn item_id(media: &Media) -> u32 {
    match media {
        ⟦or_pattern⟧ => *id,
        Media::Video { ⟦struct_field⟧ } => *id,
    }
}

fn main() {
    let m = Media::Book(42);
    println!("{}", item_id(&m));
}

tests:
#[test]
fn extracts_ids() {
    assert_eq!(item_id(&Media::Book(10)), 10);
    assert_eq!(item_id(&Media::Audio(20)), 20);
    assert_eq!(item_id(&Media::Video { id: 30 }), 30);
}
